def esc(s): return html.escape(str(s),quote=True)
def image(name,alt,eager=False,cls=''):
    from PIL import Image
    dimensions=DIMENSIONS.get(name)
    if not dimensions:
        with Image.open(SITE/'assets/img'/f'{name}.webp') as im:dimensions=im.size
    w,h=dimensions
    return f'<img src="/assets/img/{name}.webp" alt="{esc(alt)}" width="{w}" height="{h}" {"fetchpriority=\"high\"" if eager else "loading=\"lazy\""} decoding="async" class="{cls}">'
