def breadcrumbs(items):return '<nav class="breadcrumbs" aria-label="Хлебные крошки"><ol><li><a href="/">Главная</a></li>'+''.join(f'<li>{"<a href=\""+u+"\">"+esc(t)+"</a>" if u else "<span aria-current=\"page\">"+esc(t)+"</span>"}</li>' for t,u in items)+'</ol></nav>'
def page(url,title,description,body,label='',noindex=False,kind='WebPage',parent=None):
    canonical=ORIGIN+url
    crumbs=[{'@type':'ListItem','position':1,'name':'Главная','item':ORIGIN+'/'}]
    if parent:crumbs.append({'@type':'ListItem','position':2,'name':parent[0],'item':ORIGIN+parent[1]})
    if url!='/':crumbs.append({'@type':'ListItem','position':len(crumbs)+1,'name':label or title.split(' |')[0],'item':canonical})
    graph=[{'@type':'Organization','@id':ORIGIN+'/#organization','name':'Gabions','url':ORIGIN+'/','telephone':['+375333790909','+375298690231'],'logo':ORIGIN+'/assets/img/favicon.svg'}, {'@type':'WebSite','@id':ORIGIN+'/#website','url':ORIGIN+'/','name':'Gabions','publisher':{'@id':ORIGIN+'/#organization'},'inLanguage':'ru'}, {'@type':kind,'@id':canonical+'#webpage','url':canonical,'name':label or title,'description':description,'inLanguage':'ru','isPartOf':{'@id':ORIGIN+'/#website'}}]
    if url!='/':graph.append({'@type':'BreadcrumbList','@id':canonical+'#breadcrumb','itemListElement':crumbs});graph[2]['breadcrumb']={'@id':canonical+'#breadcrumb'}
    if kind=='Article':graph[2].update({'headline':label or title,'author':{'@type':'Organization','name':'Gabions','url':ORIGIN+'/o-kompanii/'},'image':[ORIGIN+'/assets/img/hero-gabion-fence.webp']})
    text=f'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{canonical}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><meta name="theme-color" content="#174f3f"><meta property="og:type" content="{'article' if kind=='Article' else 'website'}"><meta property="og:locale" content="ru_BY"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{canonical}"><link rel="icon" type="image/svg+xml" href="/assets/img/favicon.svg"><link rel="stylesheet" href="/assets/css/styles.css"><script src="/assets/js/main.js" defer></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('</','<\\/')}</script></head><body>{header(url)}<main id="main">{body}</main>{footer()}</body></html>'''
    target=SITE/('404.html' if url=='/404.html' else url.strip('/')+'/index.html' if url!='/' else 'index.html')
    target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text,encoding='utf8')
    PAGES.append({'url':url,'title':title,'index':not noindex,'file':str(target.relative_to(SITE))})
